5	 * This file is part of the Predator-Prey Simulation.
6	 *
7	 * Abstract base for animals that maintain a food level and starve when it
8	 * reaches zero. Predators and Scavengers share identical act(), foodLevel,
9	 * incrementFoodLevel(), and incrementHunger() — all are defined once here.
10	 *
11	 * @version 2022.03.02
12	 */
13	public abstract class HungryAnimal extends Animal {
14	
15	    private static final Random rand = Randomizer.getRandom();
16	
17	    private int foodLevel;
18	
19	    /**
20	     * Constructor for a HungryAnimal.
21	     *
22	     * @param traits    Species-level configuration.
23	     * @param foodLevel Initial food level.
24	     * @param randomAge Whether to assign a random age.
25	     * @param field     The field in which this animal resides.
26	     * @param location  The location in which this animal spawns into.
27	     */
28	    public HungryAnimal(AnimalTraits traits, int foodLevel, boolean randomAge,
29	                        Field field, Location location) {
30	        super(traits, randomAge, field, location);
31	        this.foodLevel = foodLevel;
32	    }
33	
34	    /**
35	     * Performs one simulation step: ages, hungers, breeds, spreads disease,
36	     * searches for food, and moves. Skips acting entirely during rest period.
37	     */
38	    @Override
39	    public void act(List<Organism> newOrganisms, Weather weather, TimeOfDay time) {
40	        incrementAge();
41	        incrementHunger();
42	        if (isAlive()) {
43	            giveBirth(newOrganisms);
44	            if (time == getRestTime()) return;
45	            if (rand.nextDouble() <= getDeathByDiseaseProbability()) {
46	                remove();
47	                return;
48	            }
49	            Location newLocation = rand.nextDouble() <= getDiseaseSpreadProbability()
50	                ? findAnimalToInfect() : findFood();
51	            if (newLocation == null) {
52	                newLocation = getField().freeAdjacentLocation(getLocation());
53	            }
54	            if (newLocation != null) {
55	                setLocation(newLocation);
56	            } else {
57	                remove();
58	            }
59	        }
60	    }
61	
62	    /** Increases food level by the given amount. */
63	    public void incrementFoodLevel(int amount) {
64	        foodLevel += amount;
65	    }
66	
67	    /** Decreases food level by one; removes this animal if it reaches zero. */
68	    public void incrementHunger() {
69	        foodLevel--;
70	        if (foodLevel <= 0) {
71	            remove();
72	        }
73	    }
74	}
